  microsoftStoreOnly: { 'zh-CN': '此版本由 Microsoft Store 管理，请在商店更新管理器。', 'zh-TW': '此版本由 Microsoft Store 管理，請在商店更新管理器。', en: 'This edition is managed by Microsoft Store. Update the manager in the Store.', ko: '이 버전은 Microsoft Store에서 관리합니다. 스토어에서 관리자를 업데이트하세요.', ja: 'このバージョンは Microsoft Store で管理されています。ストアで管理ツールを更新してください。', de: "Diese Edition wird vom Microsoft Store verwaltet. Aktualisieren Sie den Manager im Store.", fr: "Cette édition est gérée par Microsoft Store. Mettez à jour le gestionnaire dans le Store.", it: "Questa edizione è gestita da Microsoft Store. Aggiornare il manager nello Store.", 'es-ES': "Esta edición es gestionada por Microsoft Store. Actualice el administrador en la tienda.", ru: "Это издание управляется Microsoft Store. Обновить менеджер в Магазине.", pl: "Ta edycja jest zarządzana przez Microsoft Store. Aktualizuj menedżera w Sklepie.", 'pt-BR': "Esta edição é gerenciada pela Microsoft Store. Atualize o gerenciador na Loja." },
  microsoftStoreOpened: { 'zh-CN': '已打开 Microsoft Store，请在商店查看更新。', 'zh-TW': '已開啟 Microsoft Store，請在商店查看更新。', en: 'Microsoft Store opened. Check for updates in the Store.', ko: 'Microsoft Store를 열었습니다. 스토어에서 업데이트를 확인하세요.', ja: 'Microsoft Store を開きました。ストアで更新をご確認ください。', de: "Microsoft Store wurde geöffnet. Überprüfen Sie im Store nach Updates.", fr: "Microsoft Store ouvert. Vérifier les mises à jour dans le Store.", it: "Microsoft Store aperto. Controllare gli aggiornamenti nel negozio.", 'es-ES': "Microsoft Store abrió. Compruebe las actualizaciones en la tienda.", ru: "Microsoft Store открылся. Проверьте наличие обновлений в Магазине.", pl: "Microsoft Store otwarty. Sprawdź aktualizacje w Sklepie.", 'pt-BR': "A Microsoft Store foi aberta. Verifique se há atualizações na Loja." },
  distributionUnavailable: { 'zh-CN': '无法确认当前程序的发行渠道，已停止检查或安装更新：{reason}', 'zh-TW': '無法確認目前程式的發行管道，已停止檢查或安裝更新：{reason}', en: 'Could not determine the app distribution. Update checking or installation was stopped: {reason}', ko: '앱 배포 경로를 확인할 수 없어 업데이트 확인 또는 설치를 중단했습니다: {reason}', ja: 'アプリの配布元を確認できないため、更新の確認またはインストールを停止しました：{reason}', de: "Die app-Verteilung konnte nicht ermittelt werden. Aktualisierungsprüfung oder Installation wurde gestoppt: {reason}", fr: "Impossible de déterminer la distribution de app. La vérification ou l'installation des mises à jour a été arrêtée : {reason}", it: "Non è possibile determinare la distribuzione app. Il controllo o l'installazione dell'aggiornamento è stato interrotto: {reason}", 'es-ES': "No se pudo determinar la distribución appZ. Se detuvo el control de actualización o la instalación: {reason}", ru: "Не удалось определить дистрибутив app. Проверка или установка обновлений остановлена: {reason}", pl: "Nie można określić dystrybucji app. Uaktualnienie kontroli lub instalacji zostało wstrzymane: {reason}", 'pt-BR': "Não foi possível determinar a distribuição app. A verificação ou instalação da atualização foi interrompida: {reason}" },
